#!/usr/bin/env python3
"""Update HWPX document with new field values and follow-ups."""

import zipfile
import xml.etree.ElementTree as ET
import csv
import json
import os
import shutil

# Register namespace to preserve it during output
ET.register_namespace('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')
ET.register_namespace('opf', 'http://www.idpf.org/2007/opf')

NAMESPACE = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

def load_renewal_data(json_path):
    """Load renewal update data from JSON."""
    with open(json_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def load_followups(csv_path):
    """Load followups from CSV and sort by sequence."""
    followups = []
    with open(csv_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            followups.append({
                'sequence': int(row['sequence']),
                'item': row['item']
            })
    followups.sort(key=lambda x: x['sequence'])
    return [f['item'] for f in followups]

def remove_linesegarray(p_elem):
    """Remove layout cache elements from a paragraph."""
    for lineseg in p_elem.findall('hp:linesegarray', NAMESPACE):
        p_elem.remove(lineseg)

def get_full_text(p_elem):
    """Get full text content of a paragraph by concatenating all text runs."""
    texts = []
    for t in p_elem.findall('.//hp:t', NAMESPACE):
        if t.text:
            texts.append(t.text)
    return ''.join(texts)

def set_text_in_run(run_elem, new_text):
    """Set text in a run element, creating hp:t if needed."""
    t_elem = run_elem.find('hp:t', NAMESPACE)
    if t_elem is None:
        t_elem = ET.SubElement(run_elem, '{http://www.hancom.co.kr/hwpml/2010/HWPML}t')
    t_elem.text = new_text

def update_section0(xml_path, data):
    """Update section0.xml with new field values."""
    tree = ET.parse(xml_path)
    root = tree.getroot()

    modified_paras = set()

    # Find all paragraphs
    for p in root.findall('hp:p', NAMESPACE):
        full_text = get_full_text(p)

        # Customer: "고객사: Northwind Retail" -> split across runs
        if '고객사: Northwind' in full_text and 'Retail' in full_text:
            runs = p.findall('hp:run', NAMESPACE)
            for i, run in enumerate(runs):
                t_elem = run.find('hp:t', NAMESPACE)
                if t_elem is not None and t_elem.text:
                    if 'Northwind' in t_elem.text:
                        t_elem.text = data['customer']
                        modified_paras.add(p.get('id'))
                    elif t_elem.text == 'Retail':
                        t_elem.text = ''  # Clear the second part
                        modified_paras.add(p.get('id'))

        # Owner: "현 담당자: 이전담당자"
        elif '현 담당자: 이전담당자' in full_text:
            for run in p.findall('hp:run', NAMESPACE):
                t_elem = run.find('hp:t', NAMESPACE)
                if t_elem is not None and t_elem.text and '이전담당자' in t_elem.text:
                    t_elem.text = t_elem.text.replace('이전담당자', data['owner_name'])
                    modified_paras.add(p.get('id'))

        # Window dates: "2025-04-01 ~ 2025-04-15"
        elif '2025-04-01 ~ 2025-04-15' in full_text:
            for run in p.findall('hp:run', NAMESPACE):
                t_elem = run.find('hp:t', NAMESPACE)
                if t_elem is not None and t_elem.text:
                    if '2025-04-01 ~ 2025-04-15' in t_elem.text:
                        t_elem.text = t_elem.text.replace('2025-04-01 ~ 2025-04-15',
                            f"{data['window_start']} ~ {data['window_end']}")
                        modified_paras.add(p.get('id'))

        # Pricing note
        elif '가격 메모: 기존 메모를 새 메모로 바꾸세요.' in full_text:
            for run in p.findall('hp:run', NAMESPACE):
                t_elem = run.find('hp:t', NAMESPACE)
                if t_elem is not None and t_elem.text:
                    if '기존 메모를 새 메모로 바꾸세요.' in t_elem.text:
                        t_elem.text = f"가격 메모: {data['note']}"
                        modified_paras.add(p.get('id'))

    # Process table cells for band and escalation
    for tbl in root.findall('hp:tbl', NAMESPACE):
        for tr in tbl.findall('hp:tr', NAMESPACE):
            for tc in tr.findall('hp:tc', NAMESPACE):
                for sublist in tc.findall('hp:subList', NAMESPACE):
                    for p in sublist.findall('hp:p', NAMESPACE):
                        full_text = get_full_text(p)

                        # Pricing band: "Standard-18M" -> "Priority-24M"
                        if 'Standard-18M' in full_text:
                            for run in p.findall('hp:run', NAMESPACE):
                                t_elem = run.find('hp:t', NAMESPACE)
                                if t_elem is not None and t_elem.text:
                                    if 'Standard-18M' in t_elem.text:
                                        t_elem.text = t_elem.text.replace('Standard-18M', data['band'])
                                        modified_paras.add(p.get('id'))

                        # Escalation email
                        elif 'ops-old@northwind.example' in full_text:
                            for run in p.findall('hp:run', NAMESPACE):
                                t_elem = run.find('hp:t', NAMESPACE)
                                if t_elem is not None and t_elem.text:
                                    if 'ops-old@northwind.example' in t_elem.text:
                                        t_elem.text = t_elem.text.replace('ops-old@northwind.example', data['escalation_email'])
                                        modified_paras.add(p.get('id'))

    # Remove linesegarray from modified paragraphs
    for p in root.findall('hp:p', NAMESPACE):
        if p.get('id') in modified_paras:
            remove_linesegarray(p)

    tree.write(xml_path, encoding='UTF-8', xml_declaration=True)
    return True

def update_section1(xml_path, followups):
    """Update section1.xml with new followups."""
    tree = ET.parse(xml_path)
    root = tree.getroot()

    modified_paras = set()

    # Find paragraphs with old follow-ups (ids 41, 42, 43)
    followup_map = {
        '41': followups[0] if len(followups) > 0 else None,
        '42': followups[1] if len(followups) > 1 else None,
        '43': followups[2] if len(followups) > 2 else None
    }

    for p in root.findall('hp:p', NAMESPACE):
        pid = p.get('id')
        if pid in followup_map and followup_map[pid]:
            # Replace the text content
            for run in p.findall('hp:run', NAMESPACE):
                t_elem = run.find('hp:t', NAMESPACE)
                if t_elem is not None and t_elem.text:
                    # Check if it contains old follow-up pattern
                    if t_elem.text.startswith(('1.', '2.', '3.')):
                        # Keep the number prefix, replace the rest
                        prefix = t_elem.text.split('.')[0] + '. '
                        t_elem.text = prefix + followup_map[pid]
                        modified_paras.add(pid)

        # Update dates in the "갱신 윈도우 확인" line
        full_text = get_full_text(p)
        if '갱신 윈도우 확인: 2025-04-01 ~ 2025-04-15' in full_text:
            for run in p.findall('hp:run', NAMESPACE):
                t_elem = run.find('hp:t', NAMESPACE)
                if t_elem is not None and t_elem.text:
                    if '2025-04-01 ~ 2025-04-15' in t_elem.text:
                        t_elem.text = t_elem.text.replace('2025-04-01 ~ 2025-04-15',
                            f"2026-08-12 ~ 2026-08-26")
                        modified_paras.add(pid)

    # Remove linesegarray from modified paragraphs
    for p in root.findall('hp:p', NAMESPACE):
        if p.get('id') in modified_paras:
            remove_linesegarray(p)

    tree.write(xml_path, encoding='UTF-8', xml_declaration=True)
    return True

def verify_appendix(xml_path):
    """Verify appendix sentence is preserved."""
    tree = ET.parse(xml_path)
    root = tree.getroot()

    appendix_found = False
    for p in root.findall('hp:p', NAMESPACE):
        full_text = get_full_text(p)
        if '이 부록 문단은 그대로 유지해야 합니다.' in full_text:
            appendix_found = True
            break

    return appendix_found

def repackage_hwpx(source_dir, output_path):
    """Repackage the modified files into a new HWPX."""
    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(source_dir):
            for file in files:
                file_path = os.path.join(root, file)
                arcname = os.path.relpath(file_path, source_dir)
                zf.write(file_path, arcname)

def main():
    # Paths
    hwpx_path = '/root/renewal_playbook.hwpx'
    json_path = '/root/renewal_update.json'
    csv_path = '/root/followups.csv'
    output_path = '/root/renewal_playbook_updated.hwpx'
    work_dir = '/tmp/hwpx_work'

    # Clean up and create work directory
    if os.path.exists(work_dir):
        shutil.rmtree(work_dir)
    os.makedirs(work_dir)

    # Extract HWPX
    with zipfile.ZipFile(hwpx_path, 'r') as zf:
        zf.extractall(work_dir)

    # Load data
    data = load_renewal_data(json_path)
    followups = load_followups(csv_path)

    print(f"Loaded renewal data: {data}")
    print(f"Loaded followups: {followups}")

    # Update section0.xml
    section0_path = os.path.join(work_dir, 'Contents', 'section0.xml')
    update_section0(section0_path, data)
    print("Updated section0.xml")

    # Update section1.xml
    section1_path = os.path.join(work_dir, 'Contents', 'section1.xml')
    update_section1(section1_path, followups)
    print("Updated section1.xml")

    # Verify appendix is preserved
    if not verify_appendix(section1_path):
        print("ERROR: Appendix sentence not found!")
        return False
    print("Verified appendix sentence is preserved")

    # Repackage
    repackage_hwpx(work_dir, output_path)
    print(f"Created updated HWPX: {output_path}")

    return True

if __name__ == '__main__':
    success = main()
    exit(0 if success else 1)

