    """Update section1.xml with new followups."""
    tree = ET.parse(xml_path)
    root = tree.getroot()

    modified_paras = set()

    # Find paragraphs with old follow-ups (ids 41, 42, 43)
    followup_map = {
        '41': followups[0] if len(followups) > 0 else None,
        '42': followups[1] if len(followups) > 1 else None,
