    }

    for p in root.findall('hp:p', NAMESPACE):
        pid = p.get('id')
        if pid in followup_map and followup_map[pid]:
            # Replace the text content
            for run in p.findall('hp:run', NAMESPACE):
                t_elem = run.find('hp:t', NAMESPACE)
                if t_elem is not None and t_elem.text:
