        full_text = get_full_text(p)
        if '갱신 윈도우 확인: 2025-04-01 ~ 2025-04-15' in full_text:
            for run in p.findall('hp:run', NAMESPACE):
                t_elem = run.find('hp:t', NAMESPACE)
                if t_elem is not None and t_elem.text:
                    if '2025-04-01 ~ 2025-04-15' in t_elem.text:
                        t_elem.text = t_elem.text.replace('2025-04-01 ~ 2025-04-15',
