def verify_appendix(xml_path):
    """Verify appendix sentence is preserved."""
    tree = ET.parse(xml_path)
    root = tree.getroot()

    appendix_found = False
    for p in root.findall('hp:p', NAMESPACE):
        full_text = get_full_text(p)
        if '이 부록 문단은 그대로 유지해야 합니다.' in full_text:
            appendix_found = True
            break

    return appendix_found

def repackage_hwpx(source_dir, output_path):
    """Repackage the modified files into a new HWPX."""
    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(source_dir):
            for file in files:
                file_path = os.path.join(root, file)
                arcname = os.path.relpath(file_path, source_dir)
                zf.write(file_path, arcname)

def main():
    # Paths
    hwpx_path = '/root/renewal_playbook.hwpx'
    json_path = '/root/renewal_update.json'
    csv_path = '/root/followups.csv'
    output_path = '/root/renewal_playbook_updated.hwpx'
    work_dir = '/tmp/hwpx_work'

    # Clean up and create work directory
    if os.path.exists(work_dir):
        shutil.rmtree(work_dir)
    os.makedirs(work_dir)

    # Extract HWPX
    with zipfile.ZipFile(hwpx_path, 'r') as zf:
        zf.extractall(work_dir)

    # Load data
    data = load_renewal_data(json_path)
    followups = load_followups(csv_path)

    print(f"Loaded renewal data: {data}")
    print(f"Loaded followups: {followups}")

    # Update section0.xml
    section0_path = os.path.join(work_dir, 'Contents', 'section0.xml')
    update_section0(section0_path, data)
    print("Updated section0.xml")

    # Update section1.xml
    section1_path = os.path.join(work_dir, 'Contents', 'section1.xml')
    update_section1(section1_path, followups)
    print("Updated section1.xml")

    # Verify appendix is preserved
    if not verify_appendix(section1_path):
        print("ERROR: Appendix sentence not found!")
        return False
    print("Verified appendix sentence is preserved")

    # Repackage
    repackage_hwpx(work_dir, output_path)
    print(f"Created updated HWPX: {output_path}")

    return True

if __name__ == '__main__':
    success = main()
    exit(0 if success else 1)

